INSERT INTO `song` (`name`, `singer_id`, `album_id`, `duration`, `url`, `lyrics`, `genre`, `language`, `release_date`, `play_count`, `like_count`, `status`) VALUES
-- 周杰伦 叶惠美
('以父之名', 1, 1, 342, '/music/yifuzhiming.mp3', '以父之名\n周杰伦\n微凉的晨露 沾湿黑礼服\n石板路有雾 父在低诉\n无奈的觉悟 只能更残酷\n一切都为了通往圣堂的路\n我不想骗你\n说怀念才是自我原谅的方式\n', '流行', '国语', '2003-07-31', 1580000, 89000, 1),
('晴天', 1, 1, 269, '/music/qingtian.mp3', '晴天\n周杰伦\n故事的小黄花\n从出生那年就飘着\n童年的荡秋千\n随记忆一直晃到现在\n刮风这天 我试过握着你手\n但偏偏 雨渐渐 大到我看你不见\n', '流行', '国语', '2003-07-31', 2850000, 156000, 1),
('稻香', 1, 1, 223, '/music/daoxiang.mp3', '稻香\n周杰伦\n对这个世界如果你有太多的抱怨\n跌倒了就不敢继续往前走\n为什么人要这么的脆弱 堕落\n请你打开电视看看\n多少人为生命在努力勇敢的走下去\n我们是不是该知足\n', '流行', '国语', '2003-07-31', 1920000, 112000, 1),
('夜曲', 1, 2, 237, '/music/yequ.mp3', '夜曲\n周杰伦\n一群嗜血的蚂蚁 被腐肉所吸引\n我面无表情看孤独的风景\n失去你 爱恨开始分明\n失去你 还有什么事好关心\n当鸽子不再象征和平\n我终于提醒我\n广场上喂食的是秃鹰\n', '流行', '国语', '2005-11-01', 1280000, 76000, 1),
('七里香', 1, 2, 299, '/music/qilixiang.mp3', '七里香\n周杰伦\n窗外的麻雀在电线杆上多嘴\n你说这一句很有夏天的感觉\n手中的铅笔在纸上来来回回\n我用几行字形容你是我的谁\n秋刀鱼的滋味猫跟你都想了解\n', '流行', '国语', '2005-11-01', 2150000, 134000, 1),
('青花瓷', 1, 2, 239, '/music/qinghuaci.mp3', '青花瓷\n周杰伦\n素胚勾勒出青花笔锋浓转淡\n瓶身描绘的牡丹一如你初妆\n冉冉檀香透过窗心事我了然\n宣纸上走笔至此搁一半\n釉色渲染仕女图韵味被私藏\n而你嫣然的一笑如含苞待放\n', '中国风', '国语', '2005-11-01', 1760000, 98000, 1),

-- 林俊杰
('江南', 2, 3, 267, '/music/jiangnan.mp3', '江南\n林俊杰\n风到这里就是粘\n粘住过客的思念\n雨到这里缠成线\n缠着我们留恋人世间\n你在身边就是缘\n缘分写在三生石上面\n爱有万分之一甜\n宁愿我就葬在这一点\n', '流行', '国语', '2010-12-08', 1650000, 92000, 1),
('修炼爱情', 2, 3, 282, '/music/xiulianaiqing.mp3', '修炼爱情\n林俊杰\n修炼爱情的悲欢\n我们这些努力不简单\n快乐炼成泪水 去纪念它的笑谈\n多少天换习惯\n不哭的人也曾哭着转过身\n', '流行', '国语', '2010-12-08', 980000, 56000, 1),
('她说', 2, 3, 320, '/music/tashuo.mp3', '她说\n林俊杰\n她静悄悄地来过\n她慢慢带走承诺\n只是最后的承诺\n还是没有带走了寂寞\n我们爱的太苦 还是她给的太苦\n', '流行', '国语', '2010-12-08', 1120000, 67000, 1),

-- 陈奕迅
('十年', 3, 4, 205, '/music/shinian.mp3', '十年\n陈奕迅\n如果那两个字没有颤抖\n我不会发现 我怎么说出口\n也不过是如果\n对于明天 如果那没有出口\n我不过 是如果\n', '流行', '国语', '2005-06-07', 2340000, 145000, 1),
('浮夸', 3, 4, 289, '/music/fukua.mp3', '浮夸\n陈奕迅\n有人问我 我就会讲\n但是无人来\n我期待 到无奈\n有话要讲 得不到装载\n我的心情犹像樽盖 等被揭开\n', '流行', '粤语', '2005-06-07', 1870000, 108000, 1),
('富士山下', 3, 4, 295, '/music/fushishanxia.mp3', '富士山下\n陈奕迅\n拦路雨偏似雪花 饮泣的你冻吗\n这风褛我给你磨到有襟花\n连调了职也不怕 怎么始终牵挂\n苦心选中今天想车你回家\n', '流行', '粤语', '2005-06-07', 1560000, 89000, 1),

-- 邓紫棋
('光年之外', 4, 5, 235, '/music/guangnianzhiwai.mp3', '光年之外\n邓紫棋\n感受停在我发端的指尖\n如何瞬间 冻结时间\n记住望着我坚定的双眼\n也许已经没有明天\n面对浩瀚的星海\n我们微小得像尘埃\n', '流行', '国语', '2015-11-06', 1450000, 82000, 1),
('泡沫', 4, 5, 258, '/music/paomo.mp3', '泡沫\n邓紫棋\n阳光下的泡沫 是彩色的\n就像被骗的我 是幸福的\n追究什么对错 你的谎言\n基于你还爱我\n美丽的泡沫 虽然一刹花火\n', '流行', '国语', '2015-11-06', 1230000, 71000, 1),
('倒数', 4, 5, 210, '/music/daoshu.mp3', '倒数\n邓紫棋\n还没到的樱花季 还没用的照相机\n还没光临的餐厅 还在路上的快递\n还没拆开的礼物 还没遇见的你\n', '流行', '国语', '2015-11-06', 980000, 54000, 1),

-- 毛不易
('消愁', 5, 6, 265, '/music/xiaochou.mp3', '消愁\n毛不易\n当你走进这欢乐场\n背上所有的梦与想\n各色的脸上各色的妆\n没人记得你的模样\n三巡酒液后你在角落\n固执的唱着苦涩的歌\n', '民谣', '国语', '2018-05-31', 1780000, 103000, 1),
('像我这样的人', 5, 6, 280, '/music/xiangwozheyangderen.mp3', '像我这样的人\n毛不易\n像我这样优秀的人\n本该灿烂过一生\n怎么二十多年到头来\n还在人海里浮沉\n像我这样聪明的人\n告别了简单的一生\n怎么还是用了一段情\n去换一身伤痕\n', '民谣', '国语', '2018-05-31', 1340000, 78000, 1),
('借', 5, 6, 245, '/music/jie.mp3', '借\n毛不易\n借一盏街灯 帮我捱过天明\n借一句誓言 帮我走过困境\n借一段旋律 帮我记住这心情\n借一把吉他 弹奏这生命\n', '民谣', '国语', '2018-05-31', 870000, 49000, 1),

-- 薛之谦
('演员', 6, 7, 261, '/music/yanyuan.mp3', '演员\n薛之谦\n简单点 说话的方式简单点\n递进的情绪请省略\n你又不是个演员\n别设计那些情节\n没意见 我只想看看你怎么圆\n你难过的太表面 像没天赋的演员\n', '流行', '国语', '2013-11-11', 2120000, 128000, 1),
('认真的雪', 6, 7, 240, '/music/renzhendexue.mp3', '认真的雪\n薛之谦\n雪下得那么深 下得那么认真\n倒映出 我躺在雪中的伤痕\n夜深了 那盏灯还亮着\n陪我听雪落下的声音\n', '流行', '国语', '2013-11-11', 1560000, 91000, 1),
('丑八怪', 6, 7, 252, '/music/choubaguai.mp3', '丑八怪\n薛之谦\n世界太嘈杂 你说的情话太假\n我想要的你给不了啊\n丑八怪 能否别把灯打开\n我要的爱 出没在 漆黑一片的舞台\n', '流行', '国语', '2013-11-11', 1290000, 76000, 1),

-- 李荣浩
('李白', 7, 8, 245, '/music/libai.mp3', '李白\n李荣浩\n大部分人要我学习去看 世俗的眼光\n我认真学习了世俗的眼光 这堂课\n世俗的眼光 世俗的眼光\n大部分人要我学习去看 世俗的眼光\n', '流行', '国语', '2013-09-16', 1450000, 85000, 1),
('模特', 7, 8, 268, '/music/mote.mp3', '模特\n李荣浩\n穿什么 用什么 穿什么 用什么\n你的生活除了工作 除了购物 除了发呆\n你的生活除了工作 除了购物 除了发呆\n', '流行', '国语', '2013-09-16', 1180000, 68000, 1),
('年少有为', 7, 8, 285, '/music/nianshaoyouwei.mp3', '年少有为\n李荣浩\n电视一直闪 联络方式都还没念\n房贷车贷 保险 都还没实现\n你记得 我呀 年少有为\n', '流行', '国语', '2013-09-16', 1670000, 97000, 1),

-- 王菲
('红豆', 8, NULL, 258, '/music/hongdou.mp3', '王菲\n红豆\n还没好好地感受 雪花绽放的气候\n我们一起颤抖 会更明白 什么是温柔\n还没跟你走过 荒芜的沙丘\n可能从此以后 学会珍惜 天长和地久\n', '流行', '国语', '1998-10-02', 2560000, 167000, 1),
('传奇', 8, NULL, 265, '/music/chuanqi.mp3', '传奇\n王菲\n只是因为在人群中多看了你一眼\n再也没能忘掉你容颜\n梦想着偶然能有一天再相见\n从此我开始孤单思念\n', '流行', '国语', '2010-02-13', 1980000, 115000, 1),
('匆匆那年', 8, NULL, 289, '/music/congcongnanian.mp3', '匆匆那年\n王菲\n匆匆那年我们 究竟说了几遍 再见之后再拖延\n可惜谁有没有 爱过不是一场 七情上面的雄辩\n匆匆那年我们 一时匆忙撂下 了难以承受的诺言\n只有等别人兑现\n', '流行', '国语', '2014-11-06', 1730000, 101000, 1);

